$ErrorActionPreference = 'Stop'
$root = Resolve-Path (Join-Path $PSScriptRoot '..'); $bat = Get-ChildItem $root -Filter '*.bat'; foreach($file in $bat){ $bare = Get-Content $file.FullName | Where-Object { $_ -match '^\s*npm(\.cmd)?\s' }; if($bare){throw "Bare npm invocation in $($file.Name): $bare"} }
$temp = Join-Path $env:TEMP "root-batch-call-$PID"; New-Item -ItemType Directory -Force $temp | Out-Null; $log=Join-Path $temp 'calls.log'; $stub=Join-Path $temp 'npm.cmd'; $stubText="@echo off`r`necho %*>>$log`r`nexit /b 0"; Set-Content -LiteralPath $stub -Value $stubText; $probe=Join-Path $temp 'probe.bat'; Set-Content -LiteralPath $probe -Value "@echo off`r`ncall npm ci`r`ncall npm run build`r`necho AFTER_NPM"; $out=& cmd /c "set PATH=$temp;%PATH%&& $probe"; if($LASTEXITCODE -ne 0 -or ($out -notcontains 'AFTER_NPM') -or ((Get-Content $log) -join '|') -ne 'ci|run build'){throw 'Controlled npm stub did not prove ordered return control.'}; Remove-Item $temp -Recurse -Force; Write-Output 'PASS root batch call regression'
